2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	
8	/**
9	 * Rejects a create-owner request whose city already contains {@value #CAPACITY} or more owners,
10	 * with a 409 Conflict. City is compared case-insensitively (matching the customer-code rule).
11	 * Runs after {@link BuildOwner} and before the owner is saved, so the count reflects only
12	 * pre-existing owners.
13	 */
14	public class CheckOwnerCityCapacity {
15	
16	    /** Maximum number of owners a single city may hold. */
17	    private static final int CAPACITY = 50;
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = owner.getCity();
22	        if (city == null) {
23	            return;
24	        }
25	        int count = 0;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
28	                continue; // same record (e.g. re-save), not counted against the city
29	            }
30	            if (city.equalsIgnoreCase(existing.getCity())) {
31	                count++;
32	            }
33	        }
34	        if (count >= CAPACITY) {
35	            throw new CityAtCapacityException(city, count);
36	        }
37	    }
38	}
